1457	// Per-sample causal self-attention FORWARD over a tile. qkv is bf16 HBM
1458	// [rows×3d] (q|k|v). Writes ctx fp32 HBM [rows×d] and attn weights fp32 to
1459	// `attn_w` [nSamp×H×S×S]. Each (sample,head,qpos) row is owned by one thread —
1460	// identical math to dec_forward_sample's attention block, looped over samples.
1461	__device__ __forceinline__ void dectc_attn_fwd_tile(
1462	        const __nv_bfloat16* __restrict__ qkv, int nrows,
1463	        float* __restrict__ ctx, float* __restrict__ attn_w) {
1464	    const int nsamp = nrows / dec::kSeq;
1465	    const float scale = dec::attn_scale();
1466	    const int rows_per = nsamp * dec::kHeads * dec::kSeq;   // (sample,head,qpos)
1467	    for (int r = threadIdx.x; r < rows_per; r += blockDim.x) {
1468	        const int si = r / (dec::kHeads * dec::kSeq);
1469	        const int rem = r % (dec::kHeads * dec::kSeq);
1470	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
1471	        const int qoff = hh * dec::kDhead;
1472	        const int rbase = si * dec::kSeq;        // first row of this sample
1473	        const __nv_bfloat16* qrow = qkv + (int64_t)(rbase + qi) * 3 * dec::kD + qoff;
1474	        float maxs = -CUDART_INF_F; float sc[dec::kSeq];
1475	        #pragma unroll
1476	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1477	            if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
1478	            const __nv_bfloat16* krow = qkv + (int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff;
1479	            float dot = 0.0f;
1480	            #pragma unroll
1481	            for (int t = 0; t < dec::kDhead; ++t)
1482	                dot += __bfloat162float(qrow[t]) * __bfloat162float(krow[t]);
1483	            sc[kj] = dot * scale; maxs = fmaxf(maxs, sc[kj]);
1484	        }
1485	        float denom = 0.0f;
1486	        #pragma unroll
1487	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1488	            float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f; sc[kj] = e; denom += e;
1489	        }
1490	        float invd = 1.0f / denom;
1491	        float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
1492	        #pragma unroll
1493	        for (int kj = 0; kj < dec::kSeq; ++kj) aw[kj] = sc[kj] * invd;
1494	        #pragma unroll
1495	        for (int t = 0; t < dec::kDhead; ++t) {
1496	            float acc = 0.0f;
